import("crypto/rand";"crypto/sha256";"encoding/base64";"encoding/hex";"encoding/json";"fmt";"io";"io/fs";"log";"mime";"net/http";"os";"path/filepath";"sort";"strings";"sync";"time";"github.com/pquerna/otp/totp";"github.com/skip2/go-qrcode";"golang.org/x/crypto/bcrypt")
type FI struct{Path string `json:"path"`;Size int64 `json:"size"`;MTime int64 `json:"mtime"`;Hash string `json:"hash"`;Kind string `json:"kind"`};type Change struct{Revision int64 `json:"revision"`;Device,Op,Path string;TS int64 `json:"ts"`};type Device struct{LastSeen,LastRevision int64};type Admin struct{User,PasswordHash,TOTPSecret string;Recovery map[string]bool};type State struct{Revision int64;Token string;Devices map[string]Device;Tombstones map[string]Change;Journal []Change;Admin *Admin};type Session struct{Expires int64};type LoginChallenge struct{User string;Expires int64};type App struct{root,data,statePath,trash string;mu sync.Mutex;s State;sessions map[string]Session;challenges map[string]int64;loginChallenges map[string]LoginChallenge}
